import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

good_numbers = set()
count = 0
limit = 100 # Initial search limit for x and y

# We enforce x < y to count each sum only once
for x in range(2, limit):
    for y in range(x + 1, limit):
        if gcd(x, y) > 1:
            m = x*x + y*y
            if m not in good_numbers:
                good_numbers.add(m)

# Sort and take the first 20
sorted_good_numbers = sorted(list(good_numbers))
if len(sorted_good_numbers) >= 20:
    print(f"Found {len(sorted_good_numbers)} good numbers within limit {limit}. The 20th smallest is: {sorted_good_numbers[19]}")
else:
    print(f"Only found {len(sorted_good_numbers)} good numbers within limit {limit}. Expanding search...")

